\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\pagestyle{empty}

%% ── Dark Tech Theme Colors ──
\definecolor{bgdark}{HTML}{0B0F19}
\definecolor{cardbg}{HTML}{141B2D}
\definecolor{cardbgtitledark}{HTML}{1A2238}
\definecolor{titlebg}{HTML}{0A0E1A}
\definecolor{statbg}{HTML}{111827}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{textdim}{HTML}{475569}
\definecolor{accentblue}{HTML}{3B82F6}
\definecolor{accentteal}{HTML}{06B6D4}
\definecolor{accentamber}{HTML}{F59E0B}
\definecolor{accentred}{HTML}{EF4444}
\definecolor{accentgreen}{HTML}{10B981}

% Model family colors
\definecolor{openai}{HTML}{10B981}
\definecolor{anthropic}{HTML}{F59E0B}
\definecolor{googlecol}{HTML}{3B82F6}
\definecolor{deepseek}{HTML}{EF4444}

% Row colors for bar chart
\definecolor{rowodd}{HTML}{111827}
\definecolor{roweven}{HTML}{1A2238}

\pagecolor{bgdark}
\color{textwhite}

%% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{accentblue}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{accentblue}\bfseries\arabic*.}}

%% ── Card styles (dark theme, left accent stripe) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentblue},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=cardbgtitledark,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accentblue!30},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentteal},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentteal},
    coltitle=accentteal, colbacktitle=cardbgtitledark,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accentteal!30},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentamber},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accentamber},
    coltitle=accentamber, colbacktitle=cardbgtitledark,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accentamber!30},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=accentblue!12!bgdark,
    borderline west={6pt}{0pt}{accentblue},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accentblue!50!bgdark,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accentblue!40},
    valign=top, drop shadow={opacity=0.2},
  },
}

%% ── pgfplots dark theme ──
\pgfplotsset{
  darkaxis/.style={
    axis background/.style={fill=cardbg},
    axis line style={draw=textdim},
    every tick/.style={color=textdim},
    x tick label style={color=textgray, font=\fontsize{20}{24}\selectfont},
    y tick label style={color=textgray, font=\fontsize{20}{24}\selectfont},
    xlabel style={color=textwhite, font=\fontsize{24}{28}\selectfont},
    ylabel style={color=textwhite, font=\fontsize{24}{28}\selectfont},
    legend style={fill=cardbg, draw=textdim, text=textwhite,
      font=\fontsize{20}{24}\selectfont},
    grid style={textdim!25},
    major grid style={textdim!15, thin},
  }
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════
\posterbox[
  enhanced, colback=titlebg, colframe=titlebg, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{accentblue},
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{80}{96}\selectfont\bfseries\color{textwhite}
    Aider LLM Polyglot Coding Leaderboard 2025}\\[14pt]
  {\fontsize{34}{42}\selectfont\color{accentteal}
    Benchmarking Top LLMs on 225 Exercises Across 6 Languages}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{textgray}
    aider.chat \enspace$\vert$\enspace 2025}
}

%% ══════════════════════════════════════
%% STATS BANNER
%% ══════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{accentteal!40},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    {\fontsize{68}{82}\selectfont\bfseries\color{accentblue} 88.0\%}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Top Score}
    {\fontsize{20}{26}\selectfont\color{textdim} --- GPT-5 (high)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    {\fontsize{68}{82}\selectfont\bfseries\color{accentteal} 225}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Coding Exercises}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    {\fontsize{68}{82}\selectfont\bfseries\color{accentamber} 6}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Languages Tested}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    {\fontsize{68}{82}\selectfont\bfseries\color{accentgreen} \$1.28}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{textgray} Lowest Cost Run}
  \end{minipage}
}

%% ══════════════════════════════════════
%% BENCHMARK OVERVIEW (Col 1, top)
%% ══════════════════════════════════════
\posterbox[tealcard, title={About the Benchmark}
]{name=benchmark, column=1, between=row5 and row10}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Aider: terminal-based AI pair-programming tool
    \item 225 Exercism exercises across 6 languages
    \item \% correct after 2 attempts, zero human intervention
    \item Secondary metrics: cost, edit format compliance
  \end{itemize}
  \vspace{10pt}
  \colorbox{accentteal!18!cardbg}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont
    \textcolor{accentteal}{\bfseries Languages:}
    \textcolor{textwhite}{C++, Go, Java, JavaScript, Python, Rust}%
  }}
}

%% ══════════════════════════════════════
%% TOP MODELS BY ACCURACY (Col 2-3, big)
%% ══════════════════════════════════════
\posterbox[bluecard, title={Top Models by Accuracy}
]{name=topmodels, column=2, span=2, between=row5 and row13}{
  \centering
  \begin{tikzpicture}[every node/.style={inner sep=0pt}]
    % ── Dimensions ──
    \def\barh{1.7}
    \def\bargap{0.4}
    \def\labelw{8}
    \def\chartw{33}
    \def\step{2.1}
    \def\rankw{1.2}

    % ── Percentage scale header ──
    \foreach \p in {70,75,80,85,90} {
      \pgfmathsetmacro{\xpos}{\labelw+(\p-68)/(92-68)*\chartw}
      \draw[textdim!50, thin] (\xpos, 3mm) -- (\xpos, {-15*\step-3mm});
      \node[above, text=textdim, font=\fontsize{16}{20}\selectfont]
        at (\xpos, 3mm) {\p\%};
    }

    % ── Alternating row backgrounds ──
    \foreach \i in {0,2,...,14} {
      \fill[rowodd] (\labelw, {-\i*\step}) rectangle +({\chartw}, {-\barh});
    }
    \foreach \i in {1,3,...,13} {
      \fill[roweven] (\labelw, {-\i*\step}) rectangle +({\chartw}, {-\barh});
    }

    % ── Accuracy bars + labels ──
    % index / name / pct / cost / family-color
    \foreach \i/\name/\pct/\cost/\fcol in {
      0/{o4-mini (high)}/71.1/\$4.47/openai,
      1/{Claude 3.5 Sonnet}/72.0/\$6.33/anthropic,
      2/{DeepSeek V3}/72.9/\$1.95/deepseek,
      3/{GPT-4.1}/74.7/\$5.60/openai,
      4/{Gemini 2.5 Flash}/76.4/\$1.28/googlecol,
      5/{o3 (medium)}/78.7/\$10.22/openai,
      6/{Claude 3.7 Sonnet}/79.6/\$7.81/anthropic,
      7/{DeepSeek R1}/80.4/\$3.88/deepseek,
      8/{GPT-5 (low)}/81.3/\$8.12/openai,
      9/{o3 (high)}/82.2/\$18.35/openai,
      10/{Gemini 2.5 Pro}/82.7/\$4.92/googlecol,
      11/{Claude 4.0 Sonnet}/84.0/\$9.47/anthropic,
      12/{Claude 4.0 Opus}/85.3/\$22.14/anthropic,
      13/{GPT-5 (medium)}/86.7/\$17.69/openai,
      14/{GPT-5 (high)}/88.0/\$29.08/openai%
    }{
      % Accuracy bar
      \pgfmathsetmacro{\barwidth}{(\pct-68)/(92-68)*\chartw}
      \fill[\fcol, opacity=0.85]
        (\labelw, {-\i*\step}) rectangle +({\barwidth}, {-\barh});

      % Rank number
      \pgfmathtruncatemacro{\rank}{15-\i}
      \node[anchor=east, text=textdim,
            font=\fontsize{18}{22}\selectfont\bfseries]
        at ({\labelw-\rankw-5mm}, {-\i*\step-\barh/2}) {\rank};

      % Model name
      \node[anchor=east, text=textwhite,
            font=\fontsize{20}{24}\selectfont]
        at ({\labelw-3mm}, {-\i*\step-\barh/2}) {\name};

      % Percentage
      \node[anchor=west, text=textwhite,
            font=\fontsize{20}{24}\selectfont\bfseries]
        at ({\labelw+\barwidth+2mm}, {-\i*\step-\barh/2}) {\pct\%};

      % Cost
      \node[anchor=west, text=accentamber,
            font=\fontsize{18}{22}\selectfont]
        at ({\labelw+\chartw+4mm}, {-\i*\step-\barh/2}) {\cost};
    }

    % ── Column headers ──
    \node[anchor=east, text=textdim,
          font=\fontsize{16}{20}\selectfont\bfseries]
      at ({\labelw-3mm}, 10mm) {Model};
    \node[anchor=west, text=textdim,
          font=\fontsize{16}{20}\selectfont\bfseries]
      at ({\labelw+\chartw+4mm}, 10mm) {Cost};

    % ── Legend ──
    \fill[openai]      (0, {-15.8*\step}) rectangle +(8mm, 8mm);
    \node[anchor=west, text=textwhite, font=\fontsize{18}{22}\selectfont]
      at (10mm, {-15.8*\step+4mm}) {OpenAI};
    \fill[anthropic]   (40mm, {-15.8*\step}) rectangle +(8mm, 8mm);
    \node[anchor=west, text=textwhite, font=\fontsize{18}{22}\selectfont]
      at (50mm, {-15.8*\step+4mm}) {Anthropic};
    \fill[googlecol]   (90mm, {-15.8*\step}) rectangle +(8mm, 8mm);
    \node[anchor=west, text=textwhite, font=\fontsize{18}{22}\selectfont]
      at (100mm, {-15.8*\step+4mm}) {Google};
    \fill[deepseek]    (140mm, {-15.8*\step}) rectangle +(8mm, 8mm);
    \node[anchor=west, text=textwhite, font=\fontsize{18}{22}\selectfont]
      at (150mm, {-15.8*\step+4mm}) {DeepSeek};
  \end{tikzpicture}
}

%% ══════════════════════════════════════
%% EDIT FORMAT COMPLIANCE (Col 1, middle)
%% ══════════════════════════════════════
\posterbox[ambercard, title={Edit Format Compliance}
]{name=editformat, column=1, between=row10 and row14}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textcolor{accentamber}{\bfseries diff-fenced}: 93--97\% compliance
    \item \textcolor{textgray}{\bfseries plain diff}: 85--92\% compliance
  \end{itemize}
  \vspace{8pt}
  \colorbox{accentamber!18!cardbg}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont
    \textcolor{accentamber}{\bfseries Best:}
    \textcolor{textwhite}{Claude 4.0 Opus at 97.3\% well-formed edits}%
  }}
  \vspace{10pt}
  \fontsize{26}{34}\selectfont\color{textgray}
  Format choice impacts automated pipeline reliability.
}

%% ══════════════════════════════════════
%% KEY TAKEAWAYS (Col 1, bottom)
%% ══════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row14 and row20}{
  \fontsize{28}{38}\selectfont
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{GPT-5 (high) leads} at 88.0\% but costs \$29.08
    \item \textbf{GPT-5 (medium)}: 86.7\% at \$17.69 --- best value at top tier
    \item \textbf{DeepSeek R1}: 80.4\% for \$3.88 --- budget champion
    \item \textbf{diff-fenced} yields more reliable automated edits than plain diff
  \end{enumerate}
  \vspace{12pt}
  \colorbox{accentblue!20!bgdark}{\parbox{0.92\linewidth}{%
    \fontsize{26}{34}\selectfont
    \textcolor{accentblue}{\bfseries Insight:}
    \textcolor{textwhite}{Near-top performance doesn't require top-dollar spend.}%
  }}
  \vspace{10pt}
  \centering
  {\fontsize{22}{28}\selectfont\color{textgray}
    aider.chat/blog/2025-06-llm-leaderboard}
}

%% ══════════════════════════════════════
%% COST VS ACCURACY (Col 2-3, bottom)
%% ══════════════════════════════════════
\posterbox[tealcard, title={Cost vs.\ Accuracy Trade-Off}
]{name=costaccuracy, column=2, span=2, between=row13 and row20}{
  \centering
  \begin{tikzpicture}
    \begin{axis}[
      darkaxis,
      width=460mm,
      height=290mm,
      xmode=log,
      log basis x=10,
      xmin=0.8, xmax=40,
      ymin=68, ymax=92,
      xlabel={Cost per Benchmark Run (\$)},
      ylabel={Accuracy (\%)},
      grid=major,
      xtick={1,2,5,10,20},
      xticklabels={\$1,\$2,\$5,\$10,\$20},
      ytick={70,75,80,85,90},
      legend entries={OpenAI, Anthropic, Google, DeepSeek},
      legend style={at={(0.02,0.98)}, anchor=north west,
        fill=cardbg, draw=textdim, text=textwhite,
        font=\fontsize{20}{24}\selectfont},
    ]

    % ── Best value zone ──
    \fill[accentgreen, opacity=0.07]
      (axis cs:0.8,76) rectangle (axis cs:6,92);
    \node[anchor=north east, text=accentgreen,
          font=\fontsize{18}{22}\selectfont\itshape]
      at (axis cs:5.8,91.8) {Best Value Zone};

    % ── OpenAI models ──
    \addplot[
      only marks, mark=*, mark size=5pt,
      fill=openai, draw=openai!70!black,
    ] coordinates {
      (29.08,88.0) (17.69,86.7) (18.35,82.2)
      (8.12,81.3)  (10.22,78.7) (5.60,74.7)  (4.47,71.1)
    };

    % ── Anthropic models ──
    \addplot[
      only marks, mark=square*, mark size=5pt,
      fill=anthropic, draw=anthropic!70!black,
    ] coordinates {
      (22.14,85.3) (9.47,84.0) (7.81,79.6) (6.33,72.0)
    };

    % ── Google models ──
    \addplot[
      only marks, mark=triangle*, mark size=6pt,
      fill=googlecol, draw=googlecol!70!black,
    ] coordinates {
      (4.92,82.7) (1.28,76.4)
    };

    % ── DeepSeek models ──
    \addplot[
      only marks, mark=diamond*, mark size=6pt,
      fill=deepseek, draw=deepseek!70!black,
    ] coordinates {
      (3.88,80.4) (1.95,72.9)
    };

    % ── Key model annotations ──
    \node[anchor=south west, text=textwhite,
          font=\fontsize{18}{22}\selectfont\bfseries,
          fill=cardbg, draw=accentblue, rounded corners=2pt, inner sep=3pt]
      at (axis cs:29.08,88.0) {GPT-5 (high)};

    \node[anchor=south east, text=textwhite,
          font=\fontsize{18}{22}\selectfont\bfseries,
          fill=cardbg, draw=accentamber, rounded corners=2pt, inner sep=3pt]
      at (axis cs:22.14,85.3) {Claude 4 Opus};

    \node[anchor=south, text=textwhite,
          font=\fontsize{18}{22}\selectfont\bfseries,
          fill=cardbg, draw=accentgreen, rounded corners=2pt, inner sep=3pt]
      at (axis cs:1.28,76.4) {Gemini 2.5 Flash};

    \node[anchor=north west, text=textwhite,
          font=\fontsize{18}{22}\selectfont\bfseries,
